-- Resources content for the Shown on the website settings card, the website's listening page and the new Outcomes
-- tab (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema. The prefix continues the
-- sequence past 20261109120000; see 20261103120000's header on why the prefix is a sequence number, not a date.
--
-- What changed for a reader: a query's Settings tab gained a Shown on the website card (Asked by, From, Part of,
-- written answers) and a switch that lists the query on the website's listening page. A query gained an Outcomes
-- tab. The guide is new rather than an edit of 'audience-listening-create-and-publish' so an editor's changes to
-- that guide are not touched.

select private.rc_release_guide(
  p_slug => 'audience-listening-on-the-website',
  p_tool_key => 'audience-listening',
  p_title => 'Showing a query on the website',
  p_summary => 'Choose what the website shows beside a question, list it on the listening page, and record what came of it.',
  p_screen_keys => array['audience-listening.query'],
  p_sort_order => 30,
  p_version_note => 'Shown on the website, the listening page and Outcomes',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The public website can show a query in two places: beside the question wherever it is asked, and on the listening page, which lists what is being asked now and what came of what was asked. Both are controlled from the query, in "},{"type":"text","text":"Settings","marks":[{"type":"bold"}]},{"type":"text","text":", and nothing appears until you turn it on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Shown on the website"}]},{"type":"paragraph","content":[{"type":"text","text":"In "},{"type":"text","text":"Settings","marks":[{"type":"bold"}]},{"type":"text","text":" the "},{"type":"text","text":"Shown on the website","marks":[{"type":"bold"}]},{"type":"text","text":" card holds the words that appear beside the question. Leave any of them blank to show nothing."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Asked by","marks":[{"type":"bold"}]},{"type":"text","text":": a person, for example a reporter's name."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From","marks":[{"type":"bold"}]},{"type":"text","text":": a desk or program, for example the news desk."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Part of","marks":[{"type":"bold"}]},{"type":"text","text":": a series or project this belongs to."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Written answers"}]},{"type":"paragraph","content":[{"type":"text","text":"Turn on "},{"type":"text","text":"Let people write an answer as well as record one","marks":[{"type":"bold"}]},{"type":"text","text":" and the website offers a Write choice beside Record. It is off by default. A written answer is read in the Portal like any other, but it has no audio, so it cannot be sent to transcription."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The listening page"}]},{"type":"paragraph","content":[{"type":"text","text":"Turn on "},{"type":"text","text":"List on the website's listening page","marks":[{"type":"bold"}]},{"type":"text","text":" to put the query on that page while it is open. It appears with its title and the lines above, and with no count of answers. A query that is not listed still works from its own link."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What came of it"}]},{"type":"paragraph","content":[{"type":"text","text":"Open the "},{"type":"text","text":"Outcomes","marks":[{"type":"bold"}]},{"type":"text","text":" tab and add a story, an episode or a report: a title, the date it was published, and the link readers are sent to. The summary is optional and public. The Portal does not look at the link or connect to any content system; it shows what you typed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The link must be a full https:// address."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a listed query has an outcome, the listening page shows it under what came of the question, with the number of people who answered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A question with no outcome never shows a number, however many people have answered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Removing an outcome takes it off the listening page. The story itself is not touched."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Closing a query keeps it on the listening page only if it has an outcome. A closed query without one is no longer listed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing on the listening page promises a reply. The wording is yours; keep it to what the station will actually do."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-11-09-audience-listening-on-the-website',
  p_tool_key => 'audience-listening',
  p_released_on => '2026-11-09',
  p_title => 'Queries can be shown on the website, with what came of them',
  p_guide_slugs => array['audience-listening-on-the-website'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A query has a new Outcomes tab, and Settings has a new Shown on the website card. Asked by, From and Part of are the words that appear beside the question on the website, and a switch lets people write an answer as well as record one. A second switch, List on the website's listening page, puts an open query on that page. Add a story, an episode or a report under Outcomes and the page also shows what came of the question, with the number of people who answered. A question with no outcome never shows a number. Nothing is listed until you turn it on."}]}]}$body$
);
